def tran(payload=None, wait=3.0):
    s = socket.create_connection((HOST, PORT), timeout=10)
    s.settimeout(wait)
    data = b''
    try:
        while True:
            c = s.recv(4096)
            if not c:
                break
            data += c
    except socket.timeout:
        pass
    if payload is not None:
        s.sendall(payload)
        try:
            while True:
                c = s.recv(4096)
                if not c:
                    break
                data += c
        except socket.timeout:
            pass
    try:
        s.shutdown(socket.SHUT_WR)
    except Exception:
        pass
    s.close()
    return data

